$_MODULE['<{pshubspot}prestashop>start_28b23a27ab5e1a4bcce23ddedebd5293'] = 'Dzięki tej integracji PrestaShop z HubSpot będziesz mógł automatycznie synchronizować wszystkie kontakty i / lub klientów PrestaShop z platformą HubSpot.';
$_MODULE['<{pshubspot}prestashop>start_527d858ae39f2b16f210ee47bfa10779'] = 'Po skonfigurowaniu integracji możliwe będzie:';
$_MODULE['<{pshubspot}prestashop>start_0f7942e103ec6359e031d037d4f0db22'] = 'Z łatwością twórz i wysyłaj mailingi, aby zwiększyć sprzedaż (m.in. porzucone koszyki, promocje, cross produktów, urodziny).';
$_MODULE['<{pshubspot}prestashop>start_79b7210e72e8ae585620d6c8a5458228'] = 'Szczegółowe raporty e-commerce w Hubspot.';
