$_MODULE['<{pshubspot}prestashop>start_226aa7a9c5f3c2308dca6f5a394d7f01'] = 'Będziesz mógł łatwiej zarządzać promocjami kuponowymi, będziesz mieć wszystkie swoje produkty Prestashop, w Hubspot do mailingu, strony docelowej i innych aplikacji.';
